function validate(input) {
  const [object] = input;
  const plain = /^[A-Za-z0-9]*$/;
  const stack = [[object, 0]];
  while (stack.length) {
    const [value, depth] = stack.pop();
    if (value === null || typeof value === 'boolean') continue;
    if (typeof value === 'number') {
      if (!Number.isSafeInteger(value)) return 'Numbers must be integers with |number| <= 2^53 - 1.';
      continue;
    }
    if (typeof value === 'string') {
      if (!plain.test(value)) return 'Strings may contain only letters and digits.';
      continue;
    }
    if (typeof value !== 'object') return 'Use only JSON values.';
    if (depth >= 10) return 'Nest arrays and objects at most 10 levels deep.';
    for (const key of Object.keys(value)) {
      if (!Array.isArray(value) && !plain.test(key)) return 'Keys may contain only letters and digits.';
      stack.push([value[key], depth + 1]);
    }
  }
  if (JSON.stringify(object).length > 100000) return 'The JSON text of object must be at most 10^5 characters.';
  return null;
}

