function adapt(input, solve, kit) {
  const [object] = input;
  // The problem asks for a solution without the built-in JSON.stringify, so it is switched off during the call.
  const builtIn = JSON.stringify;
  JSON.stringify = function () { throw new Error('Solve it without the built-in JSON.stringify.'); };
  let result;
  try {
    result = solve(object);
  } finally {
    JSON.stringify = builtIn;
  }
  if (typeof result !== 'string') throw new Error('jsonStringify must return a string.');
  kit.trace(`jsonStringify returns ${result.length} characters`);
  return result;
}

