function jsonStringify(object) {
  // No recursion: a stack of pending pieces, each either literal text or a value still to be written.
  let text = '';
  const stack = [{ value: object }];
  while (stack.length > 0) {
    const piece = stack.pop();
    if ('text' in piece) {
      text += piece.text;
      continue;
    }
    const value = piece.value;
    if (value === null || typeof value !== 'object') {
      text += typeof value === 'string' ? `"${value}"` : `${value}`;
      continue;
    }
    const isArray = Array.isArray(value);
    const keys = isArray ? value.map((_, index) => index) : Object.keys(value);
    const pieces = [{ text: isArray ? '[' : '{' }];
    keys.forEach((key, index) => {
      if (index > 0) pieces.push({ text: ',' });
      if (!isArray) pieces.push({ text: `"${key}":` });
      pieces.push({ value: value[key] });
    });
    pieces.push({ text: isArray ? ']' : '}' });
    // Push in reverse so the first piece is written first.
    for (let i = pieces.length - 1; i >= 0; i--) stack.push(pieces[i]);
  }
  return text;
}

