function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const characters = 'abcxyzABCXYZ0123456789';
  const word = (max) => Array.from({ length: Math.floor(rand() * (max + 1)) }, () => pick(characters)).join('');
  const maxDepth = small ? 3 : 10;
  let budget = small ? 12 : 2500;
  const leaf = () => {
    const roll = rand();
    if (roll < 0.15) return null;
    if (roll < 0.3) return rand() < 0.5;
    if (roll < 0.65) return Math.floor(rand() * 2001) - 1000;
    return word(small ? 4 : 8);
  };
  const key = () => (rand() < 0.3 ? String(Math.floor(rand() * 20)) : word(small ? 3 : 6) || 'k');
  const value = (depth) => {
    budget--;
    if (depth >= maxDepth || budget <= 0 || rand() >= 0.45) return leaf();
    const count = Math.floor(rand() * (small ? 4 : 8));
    if (rand() < 0.5) return Array.from({ length: count }, () => value(depth + 1));
    const object = {};
    for (let i = 0; i < count; i++) object[key()] = value(depth + 1);
    return object;
  };
  if (small) return [value(0)];
  // A large case is one container that keeps receiving values until the budget is spent.
  const top = rand() < 0.5 ? [] : {};
  while (budget > 0) {
    if (Array.isArray(top)) top.push(value(1));
    else top[key() + String(budget)] = value(1);
  }
  return [top];
}
